import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import {
  S3Client,
  PutObjectCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";
import * as fs from "fs/promises";
import * as path from "path";

async function main() {
  const trialIdPath = "/logs/artifacts/trial_id";
  const trialId = (await fs.readFile(trialIdPath, "utf-8")).trim();

  // Normalize bucket name: lowercase and replace non-alphanumeric (except dots/hyphens) with hyphens
  // Specifically underscores to hyphens as per instructions
  const normalizedTrialId = trialId.toLowerCase().replace(/_/g, "-");
  const sourceBucketName = `harbor-isolation-${normalizedTrialId}`;

  console.log(`Source bucket name: ${sourceBucketName}`);

  const adminConfig = {
    endpoint: "REDACTED",
    region: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  };

  let forkSet;
  try {
    const result = await createForks(sourceBucketName, 3, {
      prefix: "audit-fork",
      credentials: { role: "Editor" },
    });

    if (result.error) {
      throw new Error(`Failed to create forks: ${result.error}`);
    }

    forkSet = result.forkSet;
    if (!forkSet || forkSet.forks.length !== 3) {
      throw new Error("Failed to create 3 forks");
    }

    console.log("Forks created successfully");

    // Parallel uploads
    await Promise.all(
      forkSet.forks.map(async (fork, index) => {
        const agentKey = `agent-${index + 1}.out`;
        const client = new S3Client({
          endpoint: "REDACTED",
          region: "REDACTED",
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
        });

        console.log(`Uploading ${agentKey} to ${fork.bucketName}...`);
        await client.send(
          new PutObjectCommand({
            Bucket: fork.bucketName,
            Key: agentKey,
            Body: `Content from agent ${index + 1}`,
          })
        );
      })
    );

    console.log("Uploads complete. Starting audit...");

    // Audit Source Bucket
    const adminClient = new S3Client(adminConfig);
    const sourceObjects = await adminClient.send(
      new ListObjectsV2Command({ Bucket: sourceBucketName })
    );
    const sourceKeys = (sourceObjects.Contents || [])
      .map((o) => o.Key!)
      .sort();

    console.log(`Source keys: ${JSON.stringify(sourceKeys)}`);

    if (sourceKeys.length !== 2 || !sourceKeys.includes("seed1.txt") || !sourceKeys.includes("seed2.txt")) {
        throw new Error(`Source bucket isolation failure: Expected [seed1.txt, seed2.txt], got ${JSON.stringify(sourceKeys)}`);
    }

    // Audit Forks
    const forkResults = [];
    for (let i = 0; i < forkSet.forks.length; i++) {
      const fork = forkSet.forks[i];
      const forkClient = new S3Client({
        endpoint: "REDACTED",
        region: "REDACTED",
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });

      const forkObjects = await forkClient.send(
        new ListObjectsV2Command({ Bucket: fork.bucketName })
      );
      const forkKeys = (forkObjects.Contents || [])
        .map((o) => o.Key!)
        .sort();

      console.log(`Fork ${i} (${fork.bucketName}) keys: ${JSON.stringify(forkKeys)}`);

      const expectedAgentKey = `agent-${i + 1}.out`;

      // Validation
      if (!forkKeys.includes("seed1.txt") || !forkKeys.includes("seed2.txt")) {
          throw new Error(`Fork ${i} missing seed files`);
      }
      if (!forkKeys.includes(expectedAgentKey)) {
          throw new Error(`Fork ${i} missing its own output file ${expectedAgentKey}`);
      }
      if (forkKeys.length !== 3) {
          // Check if it contains other agents' outputs
          for (let j = 1; j <= 3; j++) {
              const otherKey = `agent-${j}.out`;
              if (j !== (i + 1) && forkKeys.includes(otherKey)) {
                  throw new Error(`Fork ${i} contains leaked object ${otherKey} from another fork`);
              }
          }
          throw new Error(`Fork ${i} has unexpected number of objects: ${JSON.stringify(forkKeys)}`);
      }

      forkResults.push({
        bucket: fork.bucketName,
        keys: forkKeys,
      });
    }

    const auditReport = {
      source_keys: sourceKeys,
      fork_results: forkResults,
    };

    await fs.writeFile(
      "/home/user/isolation/audit.json",
      JSON.stringify(auditReport, null, 2),
      "utf-8"
    );
    console.log("Audit report written to /home/user/isolation/audit.json");

  } catch (error) {
    console.error("An error occurred:", error);
    process.exit(1);
  } finally {
    if (forkSet) {
      console.log("Tearing down forks...");
      await teardownForks(forkSet);
    }
  }
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

