import { S3Client, CreateBucketCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import * as fs from "fs/promises";

async function setup() {
  const trialId = (await fs.readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const normalizedTrialId = trialId.toLowerCase().replace(/_/g, "-");
  const bucketName = `harbor-isolation-${normalizedTrialId}`;

  const client = new S3Client({
    endpoint: "REDACTED",
    region: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  console.log(`Creating bucket ${bucketName}...`);
  try {
    await client.send(new CreateBucketCommand({ Bucket: bucketName }));
    console.log("Bucket created.");
  } catch (e: any) {
    if (e.name === "BucketAlreadyOwnedByYou" || e.name === "BucketAlreadyExists") {
      console.log("Bucket already exists.");
    } else {
      throw e;
    }
  }

  console.log("Uploading seeds...");
  await client.send(new PutObjectCommand({ Bucket: bucketName, Key: "seed1.txt", Body: "seed1" }));
  await client.send(new PutObjectCommand({ Bucket: bucketName, Key: "seed2.txt", Body: "seed2" }));
  console.log("Seeds uploaded.");
}

setup().catch(console.error);

import { S3Client, ListBucketsCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";

async function findSeeds() {
  const client = new S3Client({
    endpoint: "REDACTED",
    region: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  const { Buckets } = await client.send(new ListBucketsCommand({}));
  for (const b of Buckets || []) {
    if (b.Name?.startsWith("harbor-")) {
        try {
            const { Contents } = await client.send(new ListObjectsV2Command({ Bucket: b.Name, MaxKeys: 5 }));
            if (Contents?.some(c => c.Key === "seed1.txt")) {
                console.log(`Found seeds in bucket: ${b.Name}`);
            }
        } catch (e) {}
    }
  }
}

findSeeds().catch(console.error);

import { S3Client, DeleteObjectCommand, DeleteBucketCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";

async function cleanup() {
  const client = new S3Client({
    endpoint: "REDACTED",
    region: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  const bucket = "harbor-isolation-isolated-fork-writer-audit--pwvh34e";
  try {
    const { Contents } = await client.send(new ListObjectsV2Command({ Bucket: bucket }));
    for (const c of Contents || []) {
      await client.send(new DeleteObjectCommand({ Bucket: bucket, Key: c.Key! }));
    }
    await client.send(new DeleteBucketCommand({ Bucket: bucket }));
    console.log("Cleaned up my bucket.");
  } catch (e) {}
}

cleanup().catch(console.error);

